const base = String($env.MERCHANTPRO_BASE_URL || "https://www.playworld.rs").trim().replace(/\/$/, "");
const key = String($env.MERCHANTPRO_API_KEY || "").trim();
const secret = String($env.MERCHANTPRO_API_SECRET || "").trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const statusOf = (e) => Number(e?.statusCode || e?.response?.statusCode || e?.cause?.statusCode || 0);
const bodyOf = (v) => {
  const b = v?.body ?? v;
  if (typeof b !== "string") return b;
  try { return JSON.parse(b); } catch { return null; }
};
const retryable = (s) => s === 0 || s === 429 || s >= 500;
const fail = (code, message) => [{ json: { kind: "error", load_error_code: code, load_error_message: message } }];
if (!base || !key || !secret) return fail("configuration", "MerchantPro konfiguracija nije dostupna.");
let origin;
try { origin = new URL(base); if (origin.protocol !== "https:") throw new Error(); } catch { return fail("configuration", "MERCHANTPRO_BASE_URL mora biti HTTPS URL."); }
const request = async (url, qs) => {
  for (let attempt = 0; attempt < 4; attempt += 1) {
    try {
      const response = await this.helpers.httpRequest({
        method: "GET", url, qs, auth: { username: key, password: secret },
        headers: { Accept: "application/json" }, returnFullResponse: true,
        encoding: "json", timeout: 20000
      });
      const status = Number(response?.statusCode || 200);
      if (retryable(status) && attempt < 3) { await wait(1000 * (2 ** attempt)); continue; }
      return { status, body: bodyOf(response) };
    } catch (e) {
      const status = statusOf(e);
      if (!retryable(status) || attempt === 3) throw e;
      await wait(1000 * (2 ** attempt));
    }
  }
  throw new Error("request failed");
};
const orders = [];
const seen = new Set();
let start = 0;
try {
  while (true) {
    const url = new URL("/api/v2/orders", origin);
    const pageKey = url.toString() + "?start=" + start;
    if (seen.has(pageKey)) throw new Error("repeated page");
    seen.add(pageKey);
    const page = await request(url.toString(), { shipping_status: "shipped", include: "line_items", limit: 100, start });
    if (page.status === 401 || page.status === 403) return fail("merchantpro_authentication", "MerchantPro autentikacija nije prihvaćena.");
    if (page.status === 429) return fail("merchantpro_rate_limit", "MerchantPro je privremeno ograničio zahteve.");
    if (page.status >= 500 || page.status === 0) return fail("merchantpro_server", "MerchantPro trenutno nije dostupan.");
    if (page.status < 200 || page.status >= 300 || !page.body || !Array.isArray(page.body.data)) return fail("merchantpro_invalid_response", "MerchantPro je vratio neočekivan odgovor.");
    orders.push(...page.body.data);
    const next = page.body.meta?.links?.next;
    const href = typeof next === "string" ? next : (next?.href || next?.url || "");
    if (href) {
      const nextUrl = new URL(href, origin);
      if (nextUrl.origin !== origin.origin) throw new Error("pagination origin changed");
      const nextStart = nextUrl.searchParams.get("start");
      start = nextStart && /^\d+$/.test(nextStart) ? Number(nextStart) : start + 100;
      continue;
    }
    if (page.body.data.length < 100) break;
    start += 100;
  }
} catch (e) {
  const status = statusOf(e);
  return fail(status === 401 || status === 403 ? "merchantpro_authentication" : status === 429 ? "merchantpro_rate_limit" : status >= 500 ? "merchantpro_server" : "merchantpro_network", "MerchantPro porudžbine nisu učitane.");
}
if (!orders.length) return [{ json: { kind: "empty" } }];
return orders.map((order) => ({ json: { kind: "order", order } }));

const labels = {
  configuration: "nedostaje MerchantPro konfiguracija",
  merchantpro_authentication: "MerchantPro autentikacija nije prihvaćena",
  merchantpro_rate_limit: "MerchantPro je privremeno ograničio zahteve",
  merchantpro_server: "MerchantPro trenutno nije dostupan",
  merchantpro_invalid_response: "MerchantPro je vratio neočekivan odgovor",
  merchantpro_network: "MerchantPro zahtev nije uspeo"
};
const reason = labels[$json.load_error_code] || "nepoznata greška pri učitavanju";
return [{ json: { notification_messages: ["⚠️ MerchantPro obrada nije završena\n\nRazlog: " + reason + "."] } }];

const result = [];
const quantityOf = (v) => {
  if (typeof v === "number") return Number.isInteger(v) && v >= 0 ? v : null;
  const s = String(v ?? "").trim();
  return /^\d+$/.test(s) ? Number(s) : null;
};
for (const item of $input.all()) {
  const order = item.json?.order || {};
  const orderId = String(order.id ?? "").trim();
  const display = String(order.channel_ref_id ?? order.id ?? "").trim() || orderId;
  const lines = Array.isArray(order.line_items) ? order.line_items : null;
  if (!lines) {
    result.push({ json: { has_mystery_box: true, validation_status: "invalid_order", order_id: orderId, display_number: display, quantity: 0 } });
    continue;
  }
  const mystery = lines.filter((line) => Number(line?.product_id) === 1004);
  if (!mystery.length) continue;
  let quantity = 0;
  let malformed = false;
  for (const line of mystery) {
    const parsed = quantityOf(line?.quantity);
    if (parsed === null) malformed = true;
    else quantity += parsed;
  }
  const other = lines.filter((line) => line?.item_type === "product" && Number(line?.product_id) !== 1004);
  const email = String(order.customer_email ?? "").trim();
  const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const billing = String(order.billing_name ?? "").trim();
  const shipping = String(order.shipping_name ?? "").trim();
  const validation_status = !orderId ? "invalid_order" : malformed || quantity <= 0 ? "invalid_quantity" : !validEmail ? "missing_email" : "ready";
  result.push({ json: {
    has_mystery_box: true, validation_status, order_id: orderId, display_number: display,
    email, customer_name: billing || shipping || "", quantity, mystery_only: other.length === 0
  } });
}
return result;

const reason = $json.validation_status === "missing_email" ? "nedostaje ispravna email adresa" : $json.validation_status === "invalid_quantity" ? "količina Mystery Box proizvoda nije ispravna" : "nedostaje validan ID porudžbine";
const text = "⚠️ Mystery Box nije automatski isporučen\n\nPorudžbina: " + ($json.display_number || $json.order_id || "nepoznata") + "\nRazlog: " + reason + "\nKoličina: " + String($json.quantity || 0);
return { json: { ...$json, notification_messages: [text] } };

const input = $json;
const token = String($env.PWRS_N8N_API_KEY || "").trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const statusOf = (e) => Number(e?.statusCode || e?.response?.statusCode || e?.cause?.statusCode || 0);
const bodyOf = (v) => {
  const b = v?.body ?? v;
  if (typeof b !== "string") return b;
  try { return JSON.parse(b); } catch { return null; }
};
const retryable = (s) => s === 0 || s === 429 || s >= 500;
if (!token) return { json: { ...input, fulfillment_http_status: 0, fulfillment_body: null, fulfillment_error_code: "configuration" } };
const requestBody = { order_id: String(input.order_id), email: input.email, name: input.customer_name || "", quantity: Number(input.quantity) };
for (let attempt = 0; attempt < 4; attempt += 1) {
  try {
    const response = await this.helpers.httpRequest({
      method: "POST", url: "https://shuffle.playworld.rs/api/v1/mystery-box/fulfill",
      headers: { Authorization: "Bearer " + token, Accept: "application/json", "Content-Type": "application/json" },
      body: requestBody, json: true, returnFullResponse: true, timeout: 25000
    });
    const status = Number(response?.statusCode || 200);
    if (retryable(status) && attempt < 3) { await wait(1000 * (2 ** attempt)); continue; }
    return { json: { ...input, fulfillment_http_status: status, fulfillment_body: bodyOf(response) } };
  } catch (e) {
    const status = statusOf(e);
    if (!retryable(status) || attempt === 3) {
      const code = status === 401 || status === 403 ? "authentication" : status === 409 ? "needs_review" : status === 422 ? "invalid_input" : status === 429 ? "rate_limit" : status >= 500 ? "temporary_server" : "network";
      return { json: { ...input, fulfillment_http_status: status, fulfillment_body: bodyOf(e?.response || e?.body), fulfillment_error_code: code } };
    }
    await wait(1000 * (2 ** attempt));
  }
}
return { json: { ...input, fulfillment_http_status: 0, fulfillment_body: null, fulfillment_error_code: "network" } };

const body = $json.fulfillment_body && typeof $json.fulfillment_body === "object" ? $json.fulfillment_body : {};
const data = body.data && typeof body.data === "object" ? body.data : {};
const items = Array.isArray(data.items) ? data.items : [];
const quantity = Number($json.quantity || 0);
const requested = Number(data.requested_quantity || 0);
const sent = Number(data.sent_quantity || 0);
const status = String(data.status || body.status || "").toLowerCase();
const allSent = items.length === quantity && items.every((i) => String(i?.status || "").toLowerCase() === "sent");
const success = Number($json.fulfillment_http_status) === 200 && body.success === true && status === "completed" && requested === quantity && sent === quantity && allSent;
const replay = Boolean(data.idempotent_replay);
let errorCode = $json.fulfillment_error_code || "";
if (!success && !errorCode) {
  const http = Number($json.fulfillment_http_status || 0);
  errorCode = http === 409 ? "needs_review" : http === 422 ? "invalid_input" : http === 429 ? "rate_limit" : http === 401 || http === 403 ? "authentication" : http >= 500 ? "temporary_server" : "fulfillment_failed";
}
return { json: { ...$json, fulfillment_success: success, idempotent_replay: replay, is_new_fulfillment: success && !replay, requested_quantity: requested, sent_quantity: sent, fulfillment_error_code: errorCode } };

const labels = {
  configuration: "PlayWorld API nije konfigurisan",
  authentication: "PlayWorld API autentikacija nije prihvaćena",
  needs_review: "PlayWorld isporuka zahteva ručnu proveru",
  invalid_input: "PlayWorld API nije prihvatio podatke porudžbine",
  rate_limit: "PlayWorld API je privremeno ograničio zahtev",
  temporary_server: "PlayWorld API trenutno nije dostupan",
  network: "PlayWorld API zahtev nije uspeo",
  fulfillment_failed: "PlayWorld nije potvrdio kompletnu isporuku"
};
const reason = labels[$json.fulfillment_error_code] || labels.fulfillment_failed;
const text = "⚠️ Mystery Box isporuka zahteva proveru\n\nPorudžbina: " + ($json.display_number || $json.order_id) + "\nTraženo: " + String($json.quantity) + "\nUspešno poslato: " + String($json.sent_quantity || 0) + "\nEmail: " + ($json.email || "nije naveden") + "\nRazlog: " + reason;
return { json: { ...$json, notification_messages: [text] } };

const input = $json;
const base = String($env.MERCHANTPRO_BASE_URL || "https://www.playworld.rs").trim().replace(/\/$/, "");
const key = String($env.MERCHANTPRO_API_KEY || "").trim();
const secret = String($env.MERCHANTPRO_API_SECRET || "").trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const statusOf = (e) => Number(e?.statusCode || e?.response?.statusCode || e?.cause?.statusCode || 0);
const bodyOf = (v) => {
  const b = v?.body ?? v;
  if (typeof b !== "string") return b;
  try { return JSON.parse(b); } catch { return null; }
};
if (!base || !key || !secret) return { json: { ...input, delivered_attempted: true, delivered_http_status: 0, delivered_body: null, delivered_error_code: "configuration" } };
const url = base.replace(/\/$/, "") + "/api/v2/orders/" + encodeURIComponent(String(input.order_id)) + "/delivered";
for (let attempt = 0; attempt < 4; attempt += 1) {
  try {
    const response = await this.helpers.httpRequest({
      method: "PATCH", url, auth: { username: key, password: secret },
      headers: { Accept: "application/json", "Content-Type": "application/json" },
      body: {}, json: true, returnFullResponse: true, timeout: 20000
    });
    const status = Number(response?.statusCode || 200);
    if ((status === 429 || status >= 500) && attempt < 3) { await wait(1000 * (2 ** attempt)); continue; }
    return { json: { ...input, delivered_attempted: true, delivered_http_status: status, delivered_body: bodyOf(response) } };
  } catch (e) {
    const status = statusOf(e);
    if (!((status === 0 || status === 429 || status >= 500) && attempt < 3)) {
      return { json: { ...input, delivered_attempted: true, delivered_http_status: status, delivered_body: bodyOf(e?.response || e?.body), delivered_error_code: status === 429 ? "rate_limit" : status >= 500 ? "temporary_server" : "status_update_failed" } };
    }
    await wait(1000 * (2 ** attempt));
  }
}
return { json: { ...input, delivered_attempted: true, delivered_http_status: 0, delivered_body: null, delivered_error_code: "status_update_failed" } };

const body = $json.delivered_body && typeof $json.delivered_body === "object" ? $json.delivered_body : {};
const delivered_success = Number($json.delivered_http_status) >= 200 && Number($json.delivered_http_status) < 300 && body.ok === true;
return { json: { ...$json, delivered_success } };

const input = $json;
const messages = [];
const nl = String.fromCharCode(10);
if (input.is_new_fulfillment) {
  const total = Number(input.sent_quantity || 0);
  for (let index = 1; index <= total; index += 1) {
    messages.push("🎁 Mystery Box isporučen" + nl + nl + "Porudžbina: " + (input.display_number || input.order_id) + nl + "Mystery Box: " + index + "/" + total + nl + "Email: " + input.email);
  }
}
if (input.mystery_only && input.delivered_attempted && !input.delivered_success) {
  messages.push("⚠️ MerchantPro status nije promenjen" + nl + nl + "Porudžbina: " + (input.display_number || input.order_id) + nl + "Mystery Box isporuka: uspešna" + nl + "MerchantPro status: shipped" + nl + "Pokušaj promene na delivered nije uspeo." + nl + nl + "Sledeći workflow run će pokušati ponovo.");
}
return { json: { ...input, notification_messages: messages } };

const output = [];
for (const item of $input.all()) {
  const messages = Array.isArray(item.json?.notification_messages) ? item.json.notification_messages : [];
  for (const message of messages) output.push({ json: { telegram_text: String(message), order_id: item.json.order_id || "" } });
}
return output;

const token = String($env.PWRS_TELEGRAM_BOT_TOKEN || "").trim();
const groupId = "-5462042109";
if (!token) return { json: { ...$json, telegram_ok: false, telegram_error: "Telegram bot token nije konfigurisan." } };
try {
  const response = await this.helpers.httpRequest({
    method: "POST", url: "https://api.telegram.org/bot" + token + "/sendMessage",
    headers: { Accept: "application/json", "Content-Type": "application/json" },
    body: { chat_id: groupId, text: $json.telegram_text, disable_web_page_preview: true },
    json: true, returnFullResponse: true, timeout: 15000
  });
  const body = response?.body && typeof response.body === "object" ? response.body : response;
  return { json: { ...$json, telegram_ok: body?.ok === true, telegram_error: body?.ok === true ? "" : "Telegram nije prihvatio poruku." } };
} catch {
  return { json: { ...$json, telegram_ok: false, telegram_error: "Telegram zahtev nije uspeo." } };
}
